window.VN_LEARNING=window.VN_LEARNING||{};
window.VN_LEARNING['lesson-11']={
version:1,title:'Vegetarian Diets for Children',chapter:'Chapter 13 + current pediatric guidance',duration:'80–95 minutes',
outcomes:['Explain why child vegetarian planning must protect growth, energy density and nutrient density together.','Build reliable food strategies for protein, vitamin B12, iron, zinc, calcium, vitamin D and essential fats.','Distinguish an appropriate fortified plant beverage from products that cannot replace milk nutritionally.','Use responsive feeding and age-appropriate portions without pressuring appetite.','Recognize growth, neurologic, feeding and restrictive-pattern red flags that require qualified care.'],
modules:[
{id:'growth',title:'Protect growth and energy adequacy',summary:'Start with the child’s growth pattern, appetite and small-stomach reality.',moments:[
{id:'l11-m1',title:'Growth is a pattern, not one measurement',highYield:'A child’s trajectory over time is more informative than a single weight, appetite report or comparison with peers.',teaching:['Children grow in spurts, so appetite naturally rises and falls. Assessment should use serial growth data, developmental stage, activity, health history and the family’s usual pattern rather than treating one small meal as evidence of inadequacy. Vegetarian identity alone does not predict growth failure.','Concern increases when weight or height crosses expected percentiles, development slows, energy is persistently low, eating becomes extremely restricted or the child has symptoms suggesting deficiency or disease. These findings require pediatric assessment; a food list cannot replace growth monitoring.'],keyPoints:['Appetite varies with growth rate.','Use serial growth, not one data point.','Vegetarian status alone is not a diagnosis.','Growth faltering or developmental change needs assessment.'],visual:{title:'Child nutrition assessment lens',kind:'map',items:[{label:'Trajectory',detail:'Height, weight and growth pattern over time'},{label:'Development',detail:'Skills, milestones, learning and activity'},{label:'Intake',detail:'Variety, portions, fortified foods and supplements'},{label:'Function',detail:'Energy, symptoms, feeding skills and family context'}]},mnemonic:{title:'G-D-I-F',cue:'Growth · Development · Intake · Function',explanation:'Use four lenses before judging whether the pattern is adequate.'},goodToKnow:'A healthy child can eat very different amounts from day to day; averaging intake across several days is often more useful than judging one meal.',practiceConnection:'Document growth concerns and feeding symptoms clearly and coordinate with the child’s primary-care and pediatric nutrition team rather than prescribing increasingly restrictive diets.',activity:{prompt:'Which information best shows whether a child is growing as expected?',options:[{text:'Serial measurements interpreted on an appropriate growth chart',correct:true,feedback:'Correct. A trajectory is more informative than one isolated measurement.'},{text:'Whether the child finished dinner yesterday',correct:false,feedback:'One meal does not represent growth or usual intake.'},{text:'Whether a sibling eats larger portions',correct:false,feedback:'Children differ in size, stage and appetite.'}]}},
{id:'l11-m2',title:'Energy density matters when stomachs are small',highYield:'High-fibre foods are valuable, but an all-bulky pattern can fill a young child before energy and nutrients are sufficient.',teaching:['Vegetables and fruit belong in a child’s diet, yet a pattern made mostly of low-energy produce may not supply enough energy, protein or fat. Young children often need frequent eating opportunities and compact foods such as nut or seed butters in safe forms, avocado, tofu, hummus, beans, soy foods, oils and fortified foods.','Fibre should grow gradually with variety and fluid. Fat supports energy density and essential fatty-acid intake; it should not be indiscriminately restricted in young children. Portions can begin small, with more offered when the child signals hunger.'],keyPoints:['Produce alone is not a complete child diet.','Use nutrient- and energy-dense foods.','Include appropriate fats.','Offer small portions and repeat opportunities.'],visual:{title:'Build a child-sized eating opportunity',kind:'layers',items:[{label:'Energy anchor',detail:'Grain, potato or another suitable starch'},{label:'Protein food',detail:'Beans, lentils, tofu, soy, egg or dairy as applicable'},{label:'Energy helper',detail:'Oil, avocado or safe nut/seed butter'},{label:'Produce',detail:'Fruit or vegetable in an age-safe form'}]},mnemonic:{title:'A-P-E-P',cue:'Anchor · Protein · Energy helper · Produce',explanation:'A compact checklist for balanced snacks and meals.'},goodToKnow:'Whole nuts and thick spoonfuls of nut butter can be choking hazards for young children; use age-appropriate textures and follow allergy-introduction guidance.',practiceConnection:'If a child fills quickly, improve density and frequency before simply increasing plate size. Persistent poor intake or oral-motor difficulty warrants referral.',activity:{prompt:'Which snack is most energy- and nutrient-dense for a young vegetarian child?',options:[{text:'Fortified soy yogurt with fruit and a thin swirl of seed butter',correct:true,feedback:'Correct. It combines energy, protein, fat and micronutrient potential.'},{text:'A large bowl of plain lettuce',correct:false,feedback:'Lettuce is nutritious but too low in energy and protein to stand alone.'},{text:'Unlimited juice instead of meals',correct:false,feedback:'Juice can displace more complete foods and is not a meal replacement.'}]}}
]},
{id:'nutrients',title:'Secure the nutrients that need planning',summary:'Use reliable sources and food preparation rather than vague reassurance.',moments:[
{id:'l11-m3',title:'Protein adequacy comes from pattern, amount and energy',highYield:'Children do not need complementary proteins at every meal; they need enough total energy and varied protein foods across the day.',teaching:['Legumes, tofu, tempeh, soy beverages and yogurts, textured vegetable protein, nuts and seeds in safe forms, grains, and—where included—eggs and dairy can contribute protein. Plant proteins vary in amino-acid profile and digestibility, so variety and adequate total intake matter.','The older practice of requiring beans and grains in the same meal is unnecessary for most children. Hummus and pita are still useful foods, but their value is nutrition and acceptability—not a requirement to complete protein immediately.'],keyPoints:['Adequate energy protects protein for growth.','Use varied protein foods across the day.','Same-meal combining is not required.','Texture and choking safety matter.'],visual:{title:'Protein pattern across a day',kind:'sequence',items:[{label:'Breakfast',detail:'Fortified soy beverage and oats'},{label:'Lunch',detail:'Lentil spread or tofu filling'},{label:'Snack',detail:'Soy yogurt or safe seed-butter option'},{label:'Dinner',detail:'Beans, tempeh, tofu, egg or dairy as applicable'}]},mnemonic:{title:'E-V-A',cue:'Energy · Variety · Amount',explanation:'Three conditions for a child’s protein pattern.'},goodToKnow:'Average protein intake in many vegetarian children meets recommendations, but this population observation cannot confirm an individual child’s adequacy.',practiceConnection:'Estimate intake from the actual pattern and growth context; do not assume “vegetarian” means either deficient or automatically adequate.',activity:{prompt:'What is the best current protein advice for a healthy vegetarian child?',options:[{text:'Offer varied protein foods across the day with enough total energy',correct:true,feedback:'Correct. Same-meal pairing is not required.'},{text:'Combine legumes and grains at every meal or protein is wasted',correct:false,feedback:'The body maintains amino-acid pools across meals.'},{text:'Rely only on fruit and vegetables for protein',correct:false,feedback:'A child needs more concentrated protein and energy sources.'}]}},
{id:'l11-m4',title:'B12, iron, zinc, calcium and vitamin D need reliable plans',highYield:'A vegan child requires a dependable vitamin B12 source; fortification and supplement plans must be verified, not assumed.',teaching:['Vitamin B12 deserves explicit planning because unfortified plant foods are not reliable sources. Check labels and serving frequency of fortified foods and use an age-appropriate supplement plan with qualified guidance when needed. Neurologic symptoms, developmental regression, unusual fatigue or anemia concerns require prompt medical assessment.','Nonheme iron absorption improves when iron-rich foods are paired with vitamin C. Phytate can lower iron and zinc absorption, while soaking, sprouting, fermenting and yeast leavening may help. Calcium-set tofu, fortified beverages and yogurts, and low-oxalate greens can support calcium intake; vitamin D generally requires fortified foods, supplementation according to local guidance, or both.'],keyPoints:['B12 must come from a reliable source.','Pair nonheme iron with vitamin C.','Use preparation methods that improve mineral access.','Verify calcium and vitamin D fortification.'],visual:{title:'Reliability ladder',kind:'comparison',items:[{label:'Reliable',detail:'Measured supplement or labelled fortified food used in sufficient frequency'},{label:'Variable',detail:'Product whose fortification differs by brand or market'},{label:'Unreliable',detail:'Seaweed, spirulina or fermented food claimed to supply active B12'},{label:'Clinical check',detail:'Symptoms, growth concern or lab issue requires qualified assessment'}]},mnemonic:{title:'B-I-Z-C-D',cue:'B12 · Iron · Zinc · Calcium · D',explanation:'Five nutrients to verify rather than presume.'},goodToKnow:'Cast-iron cookware can increase iron in some acidic, moist foods, but it is not a precise or sufficient treatment for iron deficiency.',practiceConnection:'Record brand, serving size and frequency for fortified products. “Plant milk” is a category, not a nutrient profile.',activity:{prompt:'Which is a dependable vitamin B12 strategy for a vegan child?',options:[{text:'A verified fortified food and/or age-appropriate supplement plan',correct:true,feedback:'Correct. Reliability and dose/frequency must be clear.'},{text:'Occasional spirulina without a label claim',correct:false,feedback:'Spirulina is not a dependable source of active B12.'},{text:'Assuming vegetables contain enough B12',correct:false,feedback:'Unfortified vegetables are not reliable B12 sources.'}]}}
]},
{id:'planning',title:'Choose age-appropriate foods and beverages',summary:'Use labels, textures and responsive feeding to make the plan workable.',moments:[
{id:'l11-m5',title:'Plant beverages are not nutritionally interchangeable',highYield:'Fortified soy beverage is often the closest plant beverage to cow’s milk for protein, but age, product and jurisdiction matter.',teaching:['Plant beverages vary widely in energy, protein, fat, calcium, vitamin D, B12, iodine, sugar and fortification. Many almond, oat, rice or coconut beverages contain little protein. A product that works in a recipe may not be suitable as a child’s main milk replacement.','For children under two, beverage decisions require pediatric guidance; ordinary plant beverages are not infant formula. For older children, compare labels and choose an appropriate unsweetened fortified product while accounting for the rest of the diet. Fortification settles, so follow storage and shaking directions.'],keyPoints:['Compare protein and energy, not just calcium.','Fortification varies by brand and country.','Plant beverage is not infant formula.','Match the beverage to the whole diet.'],visual:{title:'Plant beverage label check',kind:'sequence',items:[{label:'Age',detail:'Is this beverage appropriate at this developmental stage?'},{label:'Protein',detail:'Does it meaningfully replace the protein source being removed?'},{label:'Fortification',detail:'Calcium, vitamin D, B12 and sometimes iodine'},{label:'Sugar and use',detail:'Unsweetened for routine use; recipe use differs from drinking'}]},mnemonic:{title:'A-P-F-U',cue:'Age · Protein · Fortification · Use',explanation:'Four checks before calling a beverage a replacement.'},goodToKnow:'Goat’s milk and cow’s milk contain nutrients, but they do not automatically provide iron or solve every nutrient need; the total pattern still matters.',practiceConnection:'Photograph or record the exact label during assessment because reformulation can change the product’s role.',activity:{prompt:'Which feature most distinguishes fortified soy beverage from many other plant beverages?',options:[{text:'It often provides substantially more protein',correct:true,feedback:'Correct. Always confirm the label because products vary.'},{text:'It is always safe as infant formula',correct:false,feedback:'Ordinary soy beverage is not infant formula.'},{text:'It always contains iodine',correct:false,feedback:'Iodine fortification is variable.'}]}},
{id:'l11-m6',title:'Responsive feeding respects appetite and maintains structure',highYield:'Adults decide what, when and where food is offered; the child decides whether and how much to eat from what is offered.',teaching:['A predictable rhythm of meals and snacks gives repeated opportunities to meet needs. Small initial portions reduce overwhelm, and more can be offered. Pressuring, bribing or using very large servings to “combat” poor appetite can intensify conflict and weaken attention to hunger and fullness.','Repeated neutral exposure helps children learn foods. Include at least one familiar food without turning the meal into a short-order negotiation. Appetite changes with growth, illness, sleep, activity and developmental stage.'],keyPoints:['Use a predictable meal/snack rhythm.','Begin with child-sized portions.','Repeat exposure without coercion.','Respect hunger and fullness signals.'],visual:{title:'Responsive-feeding roles',kind:'comparison',items:[{label:'Caregiver role',detail:'What, when and where food is offered'},{label:'Child role',detail:'Whether and how much to eat'},{label:'Shared goal',detail:'Safe, calm and repeated learning opportunities'}]},mnemonic:{title:'S-O-R',cue:'Structure · Offer · Respond',explanation:'Create structure, offer variety, respond to the child’s cues.'},goodToKnow:'Continuing human milk can contribute nutrition and connection, but “longer is always better nutritionally” is too absolute; the rest of the diet and family context matter.',practiceConnection:'Ask about the mealtime relationship, not only nutrients. Feeding stress can be a central barrier even when food access is adequate.',activity:{prompt:'What is the most responsive response to variable appetite?',options:[{text:'Offer regular balanced opportunities and let the child choose how much to eat',correct:true,feedback:'Correct. Structure and autonomy work together.'},{text:'Serve much larger portions and insist they are finished',correct:false,feedback:'Pressure can worsen conflict and override appetite cues.'},{text:'Remove every refused food permanently',correct:false,feedback:'Neutral repeated exposure supports learning.'}]}}
]},
{id:'safety',title:'Recognize restriction and referral needs',summary:'Separate ordinary variation from patterns that threaten growth or development.',moments:[
{id:'l11-m7',title:'Very restrictive patterns need stronger safeguards',highYield:'Raw, fruitarian or extremely limited vegan patterns can fail to meet energy and nutrient needs in growing children.',teaching:['A vegetarian pattern can be varied and nutritionally complete, but the label does not guarantee quality. Risk rises when many food groups are excluded, supplements are rejected, the diet depends on raw bulky foods, or beliefs prevent medically necessary care.','Assess the actual foods, fortification, supplement reliability, feeding skills, growth and symptoms. Support the family respectfully while being direct about child safety. A nonjudgmental stance does not require minimizing risk.'],keyPoints:['Assess the real pattern, not the label.','Restriction can displace energy and nutrients.','Reliable supplementation may be essential.','Safety concerns require clear referral.'],visual:{title:'Restriction risk signals',kind:'map',items:[{label:'Few foods',detail:'Very narrow repertoire or whole categories removed'},{label:'Low density',detail:'Mostly raw produce with little fat/protein'},{label:'No reliable B12',detail:'Fortification and supplements rejected or inconsistent'},{label:'Growth/function change',detail:'Faltering, fatigue, regression or feeding difficulty'}]},mnemonic:{title:'F-D-B-G',cue:'Foods · Density · B12 · Growth',explanation:'Four rapid checks for a highly restrictive child pattern.'},goodToKnow:'Vegetarianism should not be blamed automatically for an unrelated condition; the risk assessment must remain specific and evidence based.',practiceConnection:'Escalate promptly for developmental regression, suspected B12 deficiency, dehydration, significant weight change, choking, persistent vomiting/diarrhea or growth faltering.',activity:{prompt:'Which pattern deserves the most urgent nutrition and medical review?',options:[{text:'A toddler on a raw fruit-heavy diet with no reliable B12 and slowing growth',correct:true,feedback:'Correct. Multiple high-risk features are present.'},{text:'A child who dislikes one vegetable',correct:false,feedback:'Single-food dislike is common.'},{text:'A child whose appetite varies across a week while growth is steady',correct:false,feedback:'Variation can be normal when the overall pattern and trajectory are sound.'}]}},
{id:'l11-m8',title:'A practical child plan links food, monitoring and follow-up',highYield:'The best plan is specific enough to implement and monitored closely enough to change when the child changes.',teaching:['Translate nutrient goals into eating opportunities: name the fortified product, serving pattern, supplement plan, protein foods, iron–vitamin C pairings and energy-dense additions. Include school, childcare, culture, allergies, budget and the child’s accepted textures.','Decide what will show progress: growth review, symptom change, expanded variety, reliable B12 use, fewer mealtime conflicts or clinician-directed laboratory follow-up. A plan without follow-up can miss both improvement and deterioration.'],keyPoints:['Specify foods, brands and frequency.','Include the child’s environment and preferences.','Choose measurable follow-up indicators.','Revise with growth and development.'],visual:{title:'Plan-to-follow-up loop',kind:'sequence',items:[{label:'Assess',detail:'Growth, pattern, barriers and red flags'},{label:'Plan',detail:'Concrete foods, fortification and supplements'},{label:'Practise',detail:'Meals, snacks, textures and routines'},{label:'Monitor',detail:'Growth, function, adherence and symptoms'},{label:'Adjust',detail:'Change the plan with new evidence'}]},mnemonic:{title:'A-P-P-M-A',cue:'Assess · Plan · Practise · Monitor · Adjust',explanation:'A child nutrition plan is a loop, not a one-time handout.'},goodToKnow:'Product fortification and child preferences can change; the plan should name alternatives rather than depend on a single product forever.',practiceConnection:'Write a concise shared-care summary so caregivers and clinicians understand which risks were assessed, what was agreed and when follow-up is due.',activity:{prompt:'Which plan is most actionable?',options:[{text:'Use a named fortified beverage, planned protein foods, an agreed B12 source and scheduled growth follow-up',correct:true,feedback:'Correct. It defines both action and monitoring.'},{text:'Tell the family only to “eat healthier”',correct:false,feedback:'The instruction is too vague to implement or evaluate.'},{text:'Wait for symptoms before checking whether B12 is reliable',correct:false,feedback:'Prevention is especially important for B12.'}]}}
]}
],
caseStudy:{title:'A small appetite and a very bulky diet',scenario:'A five-year-old vegan child follows a mostly whole-food diet. Meals are large bowls of vegetables, fruit and plain grains. The child fills quickly, has no consistent B12 source and has crossed downward on the growth chart. Caregivers believe supplements make a diet “unnatural.”',prompts:['Which findings require prompt follow-up?','How could energy and nutrient density improve without abandoning the family’s values?','What B12 message is clear, respectful and non-negotiable?','Which professionals and monitoring measures should be involved?'],takeaway:'Respectful counselling combines value-sensitive food solutions with direct protection of growth and reliable B12 provision.'},
recap:['Growth trajectory and development matter more than one meal.','Young children need enough energy density, not only high fibre and produce.','Varied protein across the day replaces obsolete same-meal combining rules.','Vegan children need a dependable B12 source.','Iron, zinc, calcium and vitamin D require deliberate food and fortification choices.','Plant beverages vary and ordinary beverages are not infant formula.','Responsive feeding uses structure without coercion.','Growth faltering, developmental change and highly restrictive patterns require qualified care.'],
flashcards:[{front:'Growth trajectory',back:'A pattern of serial measurements interpreted with development and health context.',tag:'growth'},{front:'Energy density',back:'Energy supplied per amount of food; important when a small stomach limits volume.',tag:'growth'},{front:'Responsive feeding',back:'Caregiver provides structure and options; child responds to hunger and fullness.',tag:'feeding'},{front:'Reliable B12 source',back:'A measured supplement or appropriately fortified food used in sufficient amount and frequency.',tag:'B12'},{front:'Nonheme iron enhancer',back:'Vitamin C eaten with the meal.',tag:'iron'},{front:'Zinc bioavailability',back:'Can be lowered by phytate and improved by techniques such as soaking, sprouting and fermenting.',tag:'zinc'},{front:'Calcium-set tofu',back:'Tofu made with a calcium salt; label values confirm the actual calcium amount.',tag:'calcium'},{front:'Fortified soy beverage',back:'Often the plant beverage closest to milk in protein, but age and label must be checked.',tag:'beverage'},{front:'Same-meal protein combining',back:'Not required; varied protein across the day is the current practical approach.',tag:'protein'},{front:'Child-sized portion',back:'A small starting amount with more available if hunger continues.',tag:'feeding'},{front:'Restriction red flag',back:'Narrow repertoire plus low energy density, unreliable B12, growth change or functional symptoms.',tag:'safety'},{front:'Follow-up loop',back:'Assess, plan, practise, monitor and adjust.',tag:'practice'}],
practice:[{prompt:'Why is a single meal a poor measure of adequacy?',answer:'Children’s appetite varies; serial growth, usual intake and function provide better context.',rationale:'Growth is longitudinal.',tag:'growth'},{prompt:'Give two ways to increase energy density.',answer:'Add oil, avocado, tofu, soy foods or safe nut/seed butter; use frequent balanced snacks.',rationale:'Density helps small eaters meet needs.',tag:'energy'},{prompt:'What replaces same-meal protein combining?',answer:'Adequate energy and varied protein foods across the day.',rationale:'Amino acids are pooled across meals.',tag:'protein'},{prompt:'Name a reliable vegan B12 strategy.',answer:'Verified fortified foods and/or an age-appropriate supplement plan.',rationale:'Unfortified plant foods are unreliable.',tag:'B12'},{prompt:'How can nonheme iron absorption improve?',answer:'Pair iron-rich foods with vitamin C and use suitable preparation methods.',rationale:'Meal context changes absorption.',tag:'iron'},{prompt:'What four plant-beverage checks matter?',answer:'Age appropriateness, protein, fortification and intended use.',rationale:'Products are not nutritionally interchangeable.',tag:'beverage'},{prompt:'State the responsive-feeding division of responsibility.',answer:'Caregiver chooses what, when and where; child chooses whether and how much.',rationale:'Structure and autonomy reduce pressure.',tag:'feeding'},{prompt:'Name three urgent red flags.',answer:'Growth faltering, developmental regression, suspected B12 deficiency, dehydration, persistent vomiting/diarrhea, choking or major weight change.',rationale:'These exceed routine food coaching.',tag:'safety'},{prompt:'Why can a produce-heavy diet be insufficient?',answer:'Bulk and fibre may displace energy, protein, fat and key micronutrients.',rationale:'Nutritious foods still require balance.',tag:'energy'},{prompt:'What makes a plan measurable?',answer:'Specific foods/products, frequency, supplements, follow-up date and chosen growth/function indicators.',rationale:'Specificity permits evaluation.',tag:'practice'}]
};

// Evidence-strengthening extension: nutrients and monitoring often omitted from short child-vegetarian summaries.
window.VN_LEARNING['lesson-11'].version=2;
window.VN_LEARNING['lesson-11'].sources=[{title:'Canadian Paediatric Society · Vegetarian diets for children and teens (reviewed 2024)',url:'https://caringforkids.cps.ca/handouts/preteens-and-teens/vegetarian_diets_for_children_and_teens'},{title:'Health Canada · Healthy eating for parents and children',url:'https://www.canada.ca/en/health-canada/services/food-guide/eating-support/life-stages/parents-children.html'},{title:'NIH ODS · Vitamin B12 fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/VitaminB12-HealthProfessional/'},{title:'NIH ODS · Iodine fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/Iodine-HealthProfessional/'},{title:'NIH ODS · Omega-3 fatty acids fact sheet for health professionals',url:'https://ods.od.nih.gov/factsheets/Omega3FattyAcids-HealthProfessional/'}];
window.VN_LEARNING['lesson-11'].duration='105–120 minutes';
window.VN_LEARNING['lesson-11'].outcomes.push('Plan reliable iodine and omega-3 pathways and explain why seaweed is not a precision supplement.','Choose monitoring and referral from the actual restriction, growth pattern, symptoms and supplement reliability.');
window.VN_LEARNING['lesson-11'].modules.push({id:'often-missed',title:'Catch nutrients and risks that basic checklists miss',summary:'Add iodine, omega-3 and risk-based monitoring to the familiar B12–iron–calcium plan.',moments:[
{id:'l11-m9',title:'Iodine and omega-3 need deliberate food pathways',highYield:'Iodine and long-chain omega-3 are easy to overlook because neither is guaranteed by simply eating more vegetables.',teaching:['Iodine supports thyroid hormone production and neurodevelopment. Useful sources depend on the pattern and country: iodized salt, dairy or eggs when included, and some fortified foods. Seaweed is not a precision supplement because iodine varies widely by species, harvest and portion; kelp can provide excessive amounts. Children should not be told to eat large amounts of salt, but when salt is used in family cooking the label can confirm whether it is iodized.','ALA from ground flax, chia, walnuts, canola and soy can be converted to EPA and DHA, but conversion is limited and variable. Algae-derived DHA is a direct vegetarian source. Whether a child needs a supplement depends on age, actual intake, medical context and local guidance; the useful first step is to map reliable food sources rather than assume either deficiency or adequacy.','These nutrients do not replace the core safeguards. A child with no reliable B12 source still needs a B12 plan, and seaweed should never be used as a B12 substitute.'],keyPoints:['Check whether household salt is iodized when salt is used.','Treat seaweed iodine as variable, not automatically beneficial.','Map regular ALA sources.','Consider direct DHA only in an age-appropriate, individualized plan.'],visual:{title:'Two commonly missed pathways',kind:'comparison',items:[{label:'Iodine',detail:'Iodized salt or verified foods → thyroid hormones → growth and neurodevelopment'},{label:'ALA',detail:'Flax, chia, walnuts, canola and soy → limited conversion to EPA/DHA'},{label:'Direct DHA',detail:'Age-appropriate algae-derived product when indicated'},{label:'Avoid shortcuts',detail:'Kelp is not a precise iodine dose and seaweed is not reliable B12'}]},mnemonic:{title:'I-O-A',cue:'Iodized · Omega sources · Avoid assumptions',explanation:'Verify the source, then fit it to the whole child diet.'},goodToKnow:'Specialty salts such as sea, kosher, Himalayan or gourmet salts are often not iodized unless the package explicitly says so.',practiceConnection:'Ask what salt and oils the household actually uses and how often. Brand, species and serving frequency are more informative than the words plant based.',activity:{prompt:'Which statement best describes seaweed in a child nutrition plan?',options:[{text:'Its iodine content can vary widely, so it should not be treated as a precise supplement',correct:true,feedback:'Correct. Species and portion can shift iodine from low to excessive.'},{text:'Every seaweed serving supplies a safe and predictable iodine dose',correct:false,feedback:'Iodine varies substantially among products.'},{text:'Seaweed reliably replaces vitamin B12',correct:false,feedback:'Seaweed is not a dependable source of active B12.'}]}},
{id:'l11-m10',title:'Monitoring follows the risk story—not a universal lab panel',highYield:'Diet history, growth, symptoms and supplement reliability determine what needs clinical follow-up; more testing is not automatically better.',teaching:['Begin with the actual restriction and replacement pattern. A vegan child with no dependable B12, a child with low iron intake and fatigue, and a child with good intake but a feeding-skill problem require different next steps. Intake, biochemical status, clinical deficiency and impaired growth are related but distinct; one normal value does not prove the entire pattern is adequate.','Laboratory testing is ordered and interpreted by qualified clinicians. Iron assessment may require more than hemoglobin, and ferritin can be affected by inflammation. Serum B12 can be useful but may not answer every uncertain case; clinicians may use functional markers such as methylmalonic acid in context. Iron, vitamin D and other supplements can cause harm when given inappropriately, so treatment doses should not be improvised.','Monitoring also includes function: energy, attention, development, bowel pattern, oral-motor skills, mealtime stress and participation at school. Follow-up should name the question being monitored, the action being tried and the date for reassessment.'],keyPoints:['Match follow-up to the actual restriction and symptoms.','Separate intake, biomarker, clinical and growth evidence.','Use clinician-directed laboratory interpretation.','Track function and feeding, not only numbers.'],visual:{title:'Risk-based monitoring ladder',kind:'sequence',items:[{label:'Pattern',detail:'Foods excluded, replacements, fortification and supplements'},{label:'Trajectory',detail:'Serial growth and developmental context'},{label:'Function',detail:'Energy, learning, feeding and symptoms'},{label:'Clinical decision',detail:'Targeted examination or labs when indicated'},{label:'Reassess',detail:'Was the agreed action feasible and effective?'}]},mnemonic:{title:'P-T-F-C-R',cue:'Pattern · Trajectory · Function · Clinical decision · Reassess',explanation:'Monitoring starts with a question, not a shopping list of tests.'},goodToKnow:'A supplement can correct one nutrient while leaving low energy intake, feeding difficulty or another deficiency untouched.',practiceConnection:'Document the reason for referral or testing clearly—for example, slowing growth plus a narrow repertoire and unreliable B12—rather than writing only vegan diet.',activity:{prompt:'Which is the strongest monitoring plan?',options:[{text:'Link the actual dietary risk and symptoms to targeted clinical follow-up and a reassessment date',correct:true,feedback:'Correct. The plan explains what is being checked and why.'},{text:'Order the same broad panel for every vegetarian child without context',correct:false,feedback:'Testing should be individualized and clinically interpreted.'},{text:'Wait for severe neurologic symptoms before checking B12 reliability',correct:false,feedback:'Prevention and early assessment are safer.'}]}}
]});
window.VN_LEARNING['lesson-11'].flashcards.push({front:'Iodine reliability',back:'Use verified sources such as iodized salt or labelled foods; seaweed iodine is highly variable.',tag:'iodine'},{front:'ALA and DHA',back:'ALA comes from flax, chia, walnuts, canola and soy; algae can supply preformed DHA.',tag:'omega-3'},{front:'Risk-based monitoring',back:'Connect the actual restriction, growth, symptoms and supplement reliability to targeted clinical follow-up.',tag:'monitoring'});
window.VN_LEARNING['lesson-11'].practice.push({prompt:'Why is kelp not a precision iodine supplement?',answer:'Iodine varies greatly by species, product and portion and may be excessive.',rationale:'A dependable plan needs a measurable, age-appropriate source.',tag:'iodine'},{prompt:'What four layers should a child monitoring plan connect?',answer:'Dietary pattern, growth trajectory, function or symptoms, and targeted clinical follow-up.',rationale:'These layers distinguish risk from assumption.',tag:'monitoring'});
